cmd:
cd / && rm etc/nginx/sites-enabled/default && cat > etc/nginx/sites-available/gitweb << 'EOF'
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;

    root /var/www/html;
    index index.html index.htm;

    server_name _;

    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
ln -sf etc/nginx/sites-available/gitweb etc/nginx/sites-enabled/gitweb && nginx -t 2>&1
